#!/usr/bin/env python3
"""
Flask API for sentiment analysis using Hugging Face transformer model.
"""

from flask import Flask, request, jsonify
from transformers import AutoTokenizer, AutoModelForSequenceClassification
import torch
import os

app = Flask(__name__)

# Load model and tokenizer
MODEL_PATH = "/app/model_cache/sentiment_model"

print("Loading tokenizer and model...")
try:
    tokenizer = AutoTokenizer.from_pretrained(MODEL_PATH)
    model = AutoModelForSequenceClassification.from_pretrained(MODEL_PATH)
    print("Model loaded successfully!")
except Exception as e:
    print(f"Error loading model: {e}")
    tokenizer = None
    model = None

def analyze_sentiment(text):
    """
    Analyze sentiment of the given text.

    Args:
        text (str): Text to analyze

    Returns:
        dict: Sentiment analysis results with confidence scores
    """
    if not text or not isinstance(text, str):
        return None

    try:
        # Tokenize input
        inputs = tokenizer(text, return_tensors="pt", truncation=True, padding=True, max_length=512)

        # Get model predictions
        with torch.no_grad():
            outputs = model(**inputs)

        # Apply softmax to get probabilities
        probabilities = torch.nn.functional.softmax(outputs.logits, dim=-1)

        # Extract confidence scores
        negative_score = probabilities[0][0].item()
        positive_score = probabilities[0][1].item()

        # Determine sentiment
        sentiment = "positive" if positive_score > negative_score else "negative"

        return {
            "sentiment": sentiment,
            "confidence": {
                "positive": positive_score,
                "negative": negative_score
            }
        }
    except Exception as e:
        print(f"Error during sentiment analysis: {e}")
        return None

@app.route('/health', methods=['GET'])
def health_check():
    """Health check endpoint."""
    if tokenizer is None or model is None:
        return jsonify({"status": "error", "message": "Model not loaded"}), 500
    return jsonify({"status": "healthy", "message": "Sentiment analysis API is running"})

@app.route('/sentiment', methods=['POST'])
def sentiment_analysis():
    """
    Sentiment analysis endpoint.

    Request body (JSON):
    {
        "text": "your text here"
    }

    Response (JSON):
    {
        "sentiment": "positive" or "negative",
        "confidence": {
            "positive": float (0-1),
            "negative": float (0-1)
        }
    }

    Error response (JSON):
    {
        "error": "error message"
    }
    """
    # Check if model is loaded
    if tokenizer is None or model is None:
        return jsonify({"error": "Model not loaded. Service unavailable."}), 503

    # Get JSON data from request
    data = request.get_json()

    # Validate request
    if not data:
        return jsonify({"error": "No JSON data provided"}), 400

    if 'text' not in data:
        return jsonify({"error": "Missing 'text' field in request body"}), 400

    text = data['text']

    if not isinstance(text, str):
        return jsonify({"error": "'text' field must be a string"}), 400

    if not text.strip():
        return jsonify({"error": "'text' field cannot be empty"}), 400

    # Analyze sentiment
    result = analyze_sentiment(text)

    if result is None:
        return jsonify({"error": "Failed to analyze sentiment"}), 500

    return jsonify(result)

