#include <stdlib.h>
#include <math.h>
#include <time.h>
#include <string.h>

#define DOMAIN_SIZE 10.0
#define CUTOFF_RADIUS 1.0
#define TIME_STEP 0.01
#define SIMULATION_STEPS 100
#define SEED 42

typedef struct {
    double x, y;
    double vx, vy;
    double fx, fy;
} Particle;

typedef struct {
    int *head;
    int *next;
    int nx, ny;
    double cell_size;
} Grid;

void initialize_particles(Particle *particles, int n) {
    srand(SEED);
    for (int i = 0; i < n; i++) {
        particles[i].x = ((double)rand() / RAND_MAX) * DOMAIN_SIZE;
        particles[i].y = ((double)rand() / RAND_MAX) * DOMAIN_SIZE;
        particles[i].vx = 0.0;
        particles[i].vy = 0.0;
        particles[i].fx = 0.0;
        particles[i].fy = 0.0;
    }
}

void init_grid(Grid *grid, int n) {
    grid->cell_size = CUTOFF_RADIUS;
    grid->nx = (int)(DOMAIN_SIZE / grid->cell_size) + 1;
    grid->ny = grid->nx;

    int num_cells = grid->nx * grid->ny;
    grid->head = (int*)malloc(num_cells * sizeof(int));
    grid->next = (int*)malloc(n * sizeof(int));

    for (int i = 0; i < num_cells; i++) {
        grid->head[i] = -1;
    }
}

void update_grid(Grid *grid, Particle *particles, int n) {
    int num_cells = grid->nx * grid->ny;
    for (int i = 0; i < num_cells; i++) {
        grid->head[i] = -1;
    }

    for (int i = 0; i < n; i++) {
        int gx = (int)(particles[i].x / grid->cell_size);
        int gy = (int)(particles[i].y / grid->cell_size);

        if (gx >= 0 && gx < grid->nx && gy >= 0 && gy < grid->ny) {
            int cell_idx = gy * grid->nx + gx;
            grid->next[i] = grid->head[cell_idx];
            grid->head[cell_idx] = i;
        }
    }
}

void calculate_forces(Particle *particles, int n, Grid *grid) {
    for (int i = 0; i < n; i++) {
        particles[i].fx = 0.0;
        particles[i].fy = 0.0;
    }

    for (int cy = 0; cy < grid->ny; cy++) {
        for (int cx = 0; cx < grid->nx; cx++) {
            int cell_idx = cy * grid->nx + cx;

            for (int i = grid->head[cell_idx]; i != -1; i = grid->next[i]) {
                for (int dy = -1; dy <= 1; dy++) {
                    for (int dx = -1; dx <= 1; dx++) {
                        int ncx = cx + dx;
                        int ncy = cy + dy;

                        if (ncx >= 0 && ncx < grid->nx && ncy >= 0 && ncy < grid->ny) {
                            int ncell_idx = ncy * grid->nx + ncx;

                            for (int j = grid->head[ncell_idx]; j != -1; j = grid->next[j]) {
                                if (i < j) {
                                    double dx_ij = particles[j].x - particles[i].x;
                                    double dy_ij = particles[j].y - particles[i].y;
                                    double r2 = dx_ij * dx_ij + dy_ij * dy_ij;

                                    if (r2 < CUTOFF_RADIUS * CUTOFF_RADIUS && r2 > 0) {
                                        double r = sqrt(r2);
                                        double force = 1.0 / (r2 * r);
                                        double fx = force * dx_ij / r;
                                        double fy = force * dy_ij / r;

                                        particles[i].fx -= fx;
                                        particles[i].fy -= fy;
                                        particles[j].fx += fx;
                                        particles[j].fy += fy;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

void update_positions(Particle *particles, int n) {
    for (int i = 0; i < n; i++) {
        particles[i].vx += particles[i].fx * TIME_STEP;
        particles[i].vy += particles[i].fy * TIME_STEP;

        particles[i].x += particles[i].vx * TIME_STEP;
        particles[i].y += particles[i].vy * TIME_STEP;

        if (particles[i].x < 0) particles[i].x = 0;
        if (particles[i].x > DOMAIN_SIZE) particles[i].x = DOMAIN_SIZE;
        if (particles[i].y < 0) particles[i].y = 0;
        if (particles[i].y > DOMAIN_SIZE) particles[i].y = DOMAIN_SIZE;
    }
}

double calculate_min_distance(Particle *particles, int n) {
    double min_dist = DOMAIN_SIZE;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            double dx = particles[j].x - particles[i].x;
            double dy = particles[j].y - particles[i].y;
            double dist = sqrt(dx * dx + dy * dy);
            if (dist < min_dist) {
                min_dist = dist;
            }
        }
    }
    return min_dist / CUTOFF_RADIUS;
}

double calculate_avg_distance(Particle *particles, int n) {
    double total_dist = 0.0;
    int count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            double dx = particles[j].x - particles[i].x;
            double dy = particles[j].y - particles[i].y;
            double dist = sqrt(dx * dx + dy * dy);
            total_dist += dist;
            count++;
        }
    }
    return (total_dist / count) / CUTOFF_RADIUS;
}

int main(int argc, char *argv[]) {
    int n = 0;
    char *output_file = "/app/serial.txt";
    char *summary_file = "/app/serial_summary.txt";

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-n") == 0 && i + 1 < argc) {
            n = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            summary_file = argv[i + 1];
            i++;
        }
    }

    if (n <= 0) {
        fprintf(stderr, "Error: Number of particles (-n) must be specified and positive\n");
        return 1;
    }

    Particle *particles = (Particle*)malloc(n * sizeof(Particle));
    Grid grid;

    initialize_particles(particles, n);
    init_grid(&grid, n);

    clock_t start = clock();

    for (int step = 0; step < SIMULATION_STEPS; step++) {
        update_grid(&grid, particles, n);
        calculate_forces(particles, n, &grid);
        update_positions(particles, n);
    }

    clock_t end = clock();
    double simulation_time = ((double)(end - start)) / CLOCKS_PER_SEC;

    double absmin = calculate_min_distance(particles, n);
    double absavg = calculate_avg_distance(particles, n);

    printf("n = %d, simulation time = %.6f seconds\n", n, simulation_time);
    printf("absmin = %.6f\n", absmin);
    printf("absavg = %.6f\n", absavg);

    FILE *fp = fopen(output_file, "w");
    if (fp) {
        fprintf(fp, "%d %.1f\n", n, DOMAIN_SIZE);
        for (int i = 0; i < n; i++) {
            fprintf(fp, "%.6f %.6f\n", particles[i].x, particles[i].y);
        }
        fclose(fp);
    }

    fp = fopen(summary_file, "w");
    if (fp) {
        fprintf(fp, "%d %.6f\n", n, simulation_time);
        fclose(fp);
    }

    free(particles);
    free(grid.head);
    free(grid.next);

    return 0;
}
